// TH15 synthetic training aliases (transcribe/th15/touhou-bullets.ecl, type 0..43 reuse).
// Only the types this attack uses are copied; source type is not the target appearance.
const TH15_BULLET: int = 560;    // source type13, radius 2.39999, color 8 valid
const TH15_BIG_BALL: int = 640;  // source type18, radius 8.5, color 4 valid
const TH15_OVAL: int = 672;      // source type20, radius 7, color 3 valid

// TH15 v1.00b st01mbs::MBoss1 (source lines 48-66).
// Dependencies transcribed: MBoss1_at (68-160), MBoss1_at2 (162-218).
// Clock: source t0 = card frame OPENING_BUFFER; the shell costs ~2 extra frames at startup
// (boss task first run + pattern first run), reported rather than compensated.
//
// Entry state (context_only MBoss::8-46): the mid boss is 40 of the 100 movePosTime(100,4,0,128)
// frames in at this entry, i.e. QuadOut u=0.4 at (-192,-64)+0.64*(192,192) = (-69.12,58.88),
// with moveLimit(0,128,280,256) already active. Keeping the remaining 60 frames of the same
// QuadOut reproduces the tail exactly (the residual of 1-(1-t)^2 is a scaled QuadOut).
//
// Omitted by the shared policy: setBoss/timerReset/setInterrupt/setTimeout (phase timing),
// fog, anm*, playSound, EffChargePoint3 (50, presentation only), drops.
// ANIM (etEx type2 a=1) birth slowdown and animation are omitted; its -4*velocity retreat is kept.
// SPEEDUP (type1) and BRIGHT (1048576, a=0/1) have no target form; visual only, omitted.
// %A = %A + %C (95/144) is dead in the source: both etAngle calls carry literal bases (75/123).

const TIME_LIMIT: int = 1584;      // 120 buffer + 1460 remaining source window + 4 start slack
const OPENING_BUFFER: int = 120;

// Preserved mid-interpolation entry point of MBoss's 100-frame return to (0,128).
const ENTRY_X: fx = -69.12fx;
const ENTRY_Y: fx = 58.88fx;

// etAngle(id, 1.5707964f, spread) base is a literal: 90deg (down).
const FAN_DEG: angle = 90deg;
const FAN_STEP: angle = 2deg;      // 0.034906585 rad

sub main() {
    _ = spawn_enemy(ENTRY_X, ENTRY_Y, 10000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);   // source setHitbox(40,40); ordinary circle branch uses width*0.5
    set_hurtbox(24fx);  // source setHurtbox(48,48)
    phase_begin(0, attack, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub attack() {
    wait(OPENING_BUFFER);
    // MBoss1:50-51. Remaining 60 frames of the entry QuadOut, then the source wait(160).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(160);
    // MBoss1:52 and 55: both helpers are async on the same enemy.
    spawn at2();
    spawn wave();
    loop {
        // MBoss1:56-58 / 60-62: wait(120), moveRand, wait(80) on each half.
        card_wait(120);
        card_move_rand();
        card_wait(80);
        spawn wave();
        card_wait(120);
        card_move_rand();
        card_wait(80);
        spawn wave();
    }
}

// MBoss1_at: etAim(0,1) fixed fan, sprite 13/8 then 18/4, count $F growing 1..G, one layer.
async sub wave() {
    var rank: int = global(GVAR_RANK);
    var spd: fx = 1.5fx;               // :76-84 first emitter speed, M=1 uses s0 only
    if rank == 2 { spd = 2.5fx; }
    if rank == 3 { spd = 4.1fx; }
    var gap: int = 8;                  // :98-107
    if rank == 1 { gap = 6; }
    if rank == 2 { gap = 3; }
    if rank == 3 { gap = 2; }
    var n1: int = 4;                   // diffI($G, 4, 8, 8, 12)
    if rank == 1 { n1 = 8; }
    if rank == 3 { n1 = 12; }
    var n1e: int = n1+1;
    var dist: fx = 0fx-4fx*spd;        // ANIM a=1: spawn position -= 4*velocity
    sh_reset(0);
    sh_sprite(0, TH15_BULLET, 8);      // :73
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_speed(0, spd, 0fx);             // :85 etSpeed(0, rank, 1.0) with layers=1
    sh_angle(0, FAN_DEG, FAN_STEP);    // :75
    sh_dist(0, dist);
    for k in 1..n1e {                  // :93-109 etCount($F); $F = $F+1
        sh_count(0, k, 1);
        sh_fire(0);
        wait(gap);
    }
    var spread: angle = 13deg;         // :114-121 second emitter fan spacing
    if rank == 0 { spread = 30deg; }
    if rank == 1 { spread = 20deg; }
    if rank == 2 { spread = 15deg; }
    var n2: int = 24;                  // diffI($H, 4, 8, 16, 24)
    if rank == 0 { n2 = 4; }
    if rank == 1 { n2 = 8; }
    if rank == 2 { n2 = 16; }
    sh_reset(0);
    sh_sprite(0, TH15_BIG_BALL, 4);    // :112
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_speed(0, spd, 0fx);             // :133
    sh_angle(0, FAN_DEG, spread);      // :123
    sh_dist(0, dist);
    sh_count(0, n1e, 1);               // $F keeps counting into this emitter
    for j in 0..n2 {                   // :142-158
        sh_fire(0);
        wait(gap);
    }
}

// MBoss1_at2: etNew(1), etAim(1,3) fixed ring with one way and M speed layers, re-aimed
// at the player with a +-RANDRAD/32 jitter each volley; 600 volleys, window cuts it short.
async sub at2() {
    var rank: int = global(GVAR_RANK);
    var delay: int = 300;              // :165-174
    if rank == 2 { delay = 200; }
    if rank == 3 { delay = 150; }
    wait(delay);
    var layers: int = 1;               // :178-187 n_speed
    if rank == 1 { layers = 3; }
    if rank == 2 { layers = 6; }
    if rank == 3 { layers = 3; }
    var s0: fx = 1fx;                  // :189-198 etSpeed(1, rank, 0.8)
    if rank == 2 { s0 = 3fx; }
    var s1: fx = 0.8fx;
    var step: fx = 0fx;
    if layers > 1 { step = (s1-s0)/(layers-1); }
    var gap: int = 160;                // :205-213
    if rank == 3 { gap = 80; }
    for n in 0..600 {                  // $C = 600
        // :203 etAngle(1, ANGLE_PLAYER + RANDRAD/32, 0) - one sample shared by the volley.
        var ang: angle = aim_player() + ((rand(2048)-1024) as angle);
        var ux: fx = cos(ang);
        var uy: fx = sin(ang);
        for q in 0..layers {
            var v: fx = s0;
            if layers > 1 { v = s0+step*(q as fx); }
            var d: fx = 0fx-4fx*v;     // ANIM a=1 retreat along this layer's own angle
            _ = fire(TH15_OVAL, 3, $self_x+ux*d, $self_y+uy*d, v, ang, none, none);
        }
        wait(gap);
    }
}

// TH15 st01mbs MBoss1 only. int slot0 = next movement step count; fx0/1 = logical unit vector.
// Source 412 moveRand(60,4,1.0) under MBoss moveLimit(0,128,280,256). The direction decision
// inner box is center +- (width/4, height/4) = x+-70, y64..192; the position clamp box is
// center +- (width/2, height/2) = x+-140, y0..256. Verified recipe in transcribe/th16/movement.md.
// Every source wait inside this attack uses card_wait(n) in the same owner task.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source signed unit random * pi, kept as an unwrapped BAM int.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Source does not normalize this branch before the fabs tests.
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad; nearest BAM boundaries (normal quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
